using System;using UnityEngine;using Mojinloop.Data; namespace Mojinloop.Combat { public sealed class MonsterController:MonoBehaviour { public event Action<MonsterController,int> Damaged; public event Action<MonsterController> Died; public bool IsDead{get;private set;} public int Hp{get;private set;} public MonsterData Data{get;private set;} public void Initialize(MonsterData data){Data=data;Hp=data.maxHp;IsDead=false;GetComponent<SpriteRenderer>().color=data.color;gameObject.SetActive(true);transform.localScale=Vector3.one;} public void Move(float delta){if(!IsDead)transform.position+=Vector3.left*Data.moveSpeed*delta;} public void TakeDamage(int amount){if(IsDead)return;Hp=Mathf.Max(0,Hp-amount);Damaged?.Invoke(this,amount);transform.localScale=new Vector3(1.15f,.82f,1);if(Hp<=0){IsDead=true;Died?.Invoke(this);}} } }
